# -*- coding: utf-8 -*-
import json
import os

# Загружаем исходные 77 рецептов, если файл лежит рядом
base_file = "recipes-base.json"
existing_recipes = []
existing_cats = [
    "Супы", "Вторые блюда", "Салаты", "Десерты", "Напитки",
    "Завтраки", "Выпечка", "Закуски", "Соусы"
]

if os.path.exists(base_file):
    with open(base_file, "r", encoding="utf-8") as f:
        data = json.load(f)
        existing_recipes = data.get("recipes", [])
        for c in data.get("categories", []):
            if c not in existing_cats:
                existing_cats.append(c)

# Добавляем новые категории
extra_cats = ["Рыба и морепродукты", "Гарниры", "Заготовки", "Другое"]
for c in extra_cats:
    if c not in existing_cats:
        existing_cats.append(c)

